-- SELECT only. 20261127120000_mcp_claude_read_areas 적용 전(시험 적용 전후 비교에도 씀). 카탈로그·migration 기록만 읽는다(행 값 없음).
-- 기대: 예/아니오 항목은 모두 예. 'pre-request function present'는 기록만(요청 전 함수 L1이 운영에 섰는지 — 이 migration은 그것에 기대지 않는다, 15.10).
-- 해시는 기록만 하고 사후 확인에서 같은 값이어야 한다(2판 읽기 함수·도우미·owner·운영자 기능 함수, 읽는 표의 권한·정책이 그대로라는 뜻).
-- expect: new migration absent = 예
-- expect: mcp read operator features and pin lock applied = 예
-- expect: prerequisite columns present = 예
-- expect: gate definer present = 예
-- expect: area columns absent = 예
-- expect: new functions absent = 예
-- expect: log tool check present = 예
-- expect: pre-request function present = 기록
-- expect: existing boundary hash = 기록
select 'new migration absent' as item,case when not exists(select 1 from supabase_migrations.schema_migrations where version='20261127120000') then '예' else '아니오' end as value
union all select 'mcp read operator features and pin lock applied',case when (select count(*) from supabase_migrations.schema_migrations where (version='20261120090000' and name='mcp_claude_read') or (version='20261029090000' and name='operator_features') or (version='20261119200000' and name='feature_pin_lock'))=3 then '예' else '아니오' end
union all select 'prerequisite columns present',case when (select count(*) from (values ('app_notes', 'journal_day'), ('app_notes', 'attachments'), ('app_notes', 'kind'), ('app_notes', 'raw_text'), ('app_notes', 'deleted_at'), ('app_notes', 'archived_at'), ('app_notes', 'occurred_at'), ('app_notes', 'metadata'), ('app_notes', 'title'), ('app_notes', 'ai_export_allowed'), ('app_feed_items', 'source'), ('app_feed_items', 'day'), ('app_feed_items', 'title'), ('app_feed_items', 'summary'), ('app_feed_items', 'points'), ('app_feed_items', 'counterpart'), ('app_feed_items', 'raw_text'), ('app_feed_items', 'hidden_at'), ('app_feed_items', 'archived_at'), ('app_feed_items', 'occurred_at'), ('app_call_personal', 'kind'), ('app_call_personal', 'day'), ('app_call_personal', 'title'), ('app_call_personal', 'summary'), ('app_call_personal', 'points'), ('app_call_personal', 'counterpart'), ('app_call_personal', 'raw_text'), ('app_call_personal', 'hidden_at'), ('app_call_personal', 'occurred_at'), ('app_call_edits', 'call_id'), ('app_call_edits', 'vals'), ('app_meetings', 'title'), ('app_meetings', 'meeting_at'), ('app_meetings', 'created_at'), ('app_meetings', 'transcript_text'), ('app_meetings', 'notes'), ('app_meetings', 'decisions'), ('app_meetings', 'deleted_at'), ('app_meetings', 'workspace_id'), ('app_family_notes', 'kind'), ('app_family_notes', 'body'), ('app_family_notes', 'said_when'), ('app_family_notes', 'firmness'), ('app_family_notes', 'origin'), ('app_family_notes', 'origin_day'), ('app_family_notes', 'status'), ('app_family_notes', 'created_at'), ('app_feature_locks', 'user_id'), ('app_feature_locks', 'features')) v(t,c) join pg_attribute a on a.attrelid=to_regclass('public.'||v.t) and a.attname=v.c and not a.attisdropped)=49 then '예' else '아니오' end
union all select 'gate definer present',case when exists(select 1 from pg_proc where oid=to_regprocedure('private.app_mcp_gate(text)') and prosecdef) and exists(select 1 from pg_proc where oid=to_regprocedure('private.app_workspace_has_feature(uuid,text)') and prosecdef) then '예' else '아니오' end
union all select 'area columns absent',case when not exists(select 1 from pg_attribute a where a.attrelid=to_regclass('public.app_mcp_settings') and a.attname like 'area\_%' and not a.attisdropped) then '예' else '아니오' end
union all select 'new functions absent',case when not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') and p.proname in ('app_mcp_locked_areas','app_mcp_text','app_mcp_page','app_mcp_words','app_mcp_hit','app_mcp_uuid','app_mcp_period','app_mcp_day_list','app_mcp_day_get','app_mcp_calls_list','app_mcp_call_get','app_mcp_recordings_list','app_mcp_recording_get','app_mcp_basket_search','app_mcp_basket_get','app_mcp_family_list','app_mcp_family_get')) then '예' else '아니오' end
union all select 'log tool check present',case when (select count(*) from pg_constraint c where c.conrelid=to_regclass('public.app_mcp_read_log') and c.conname='app_mcp_read_log_tool_check')=1 then '예' else '아니오' end
union all select 'pre-request function present',case when to_regprocedure('public.app_mcp_pre_request()') is not null then '예' else '아니오' end
union all select 'existing boundary hash',md5(coalesce((select string_agg(p.oid::regprocedure::text||md5(pg_get_functiondef(p.oid))||coalesce(p.proacl::text,''),',' order by p.oid::regprocedure::text) from pg_proc p where p.oid in (to_regprocedure('public.app_mcp_org_status(text)'),to_regprocedure('public.app_mcp_business_reports(date,date,text)'),to_regprocedure('public.app_mcp_project_status(text)'),to_regprocedure('public.app_mcp_ledger_search(text,text,text,date,date,integer)'),to_regprocedure('public.app_mcp_ledger_get(text)'),to_regprocedure('public.app_mcp_notes_search(text,text,integer)'),to_regprocedure('public.app_mcp_google_where()'),to_regprocedure('private.app_mcp_gate_done(text,integer,integer)'),to_regprocedure('private.app_mcp_note_locks()'),to_regprocedure('private.app_mcp_clip(text,integer)'),to_regprocedure('private.app_mcp_arg(text,integer)'),to_regprocedure('private.app_workspace_has_feature(uuid,text)'),to_regprocedure('private.app_is_workspace_owner(uuid)'))),'')||coalesce((select string_agg(c.relname::text||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid in (to_regclass('public.app_notes'),to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_meetings'),to_regclass('public.app_family_notes'),to_regclass('public.app_feature_locks'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),'')||coalesce((select string_agg(p.polrelid::regclass::text||p.polname::text||p.polcmd::text||p.polpermissive::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polrelid::regclass::text,p.polname) from pg_policy p where p.polrelid in (to_regclass('public.app_notes'),to_regclass('public.app_feed_items'),to_regclass('public.app_call_personal'),to_regclass('public.app_call_edits'),to_regclass('public.app_meetings'),to_regclass('public.app_family_notes'),to_regclass('public.app_feature_locks'),to_regclass('public.app_mcp_settings'),to_regclass('public.app_mcp_read_log'),to_regclass('public.app_workspace_members'))),''));
